INSERT INTO publications (id,submission_id,version,title,abstract,keywords,references_text,issue_id,section_id,pages,doi,copyright_holder,copyright_year,license_url,status,date_published,seq) VALUES
(6386,6386,1,'Digital Exposure of Minor Children and the Exercise of Parental Responsibility in the Peruvian Legal System','<p>This article analyzed how the digital exposure of minor children relates to the exercise of parental responsibility within the Peruvian legal system during 2025-2026. A basic study was conducted using a qualitative approach and a legal hermeneutic design. Ten legal professionals—eight lawyers, one judge, and one prosecutor—were interviewed, and ten legal documents were examined using an interview guide and a document analysis guide. The results showed that the dissemination of photographs, videos, and personal data must be evaluated based on the child''s rights to privacy, image, identity, and security. Parental representation does not represent an unrestricted right; the duty to protect encompasses the risks arising from the permanence and reproduction of content that forms a digital footprint, and progressive autonomy requires considering the child''s age, maturity, and wishes regarding the monetization of their image. The study concluded that parental rights must be exercised as a caregiving function, attending to the best interests of the child and the specific circumstances of each publication.</p>','["Children''s rights, privacy, parental responsibility, digital identity"]',NULL,37,1,'2029 - 2043',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-15',1),
(6387,6387,1,'Rüppell Fox Optimizer for Economic and Emissions Dispatch of Microgrid Involving Renewables','<p>The combined economic and emissions dispatch (CEED) of microgrids (MGs) is considered a complex optimization problem. Its goal is to balance between the costs of power generation while minimizing emissions. By integrating renewable energy sources such as solar and wind, the MG may lower its relying on high-emission conventional generators. The aim is to find the most effective power level for each resource that minimizes both the fuel consumption and the total emission output of MG. To obtain a reliable supply of energy, the dispatch process must meet physical and operational constraints. Furthermore, the total power produced by combined renewable and traditional sources must be equal to or greater than the total loads. Additionally, each generator operates within certain boundaries that reduce the equipment overstress. The utilization of the Rüppell Fox Optimizer (RFO) offers superior performance in balancing the intermittent nature of RESs with conventional generation in the MG. By simulating advanced foraging behaviors, RFO identifies the optimum operating points that minimize both total operation costs and emissions while satisfying MG different constraints. Comparative results verify that RFO achieves lowest total costs than standard meta-heuristic methods, proving its robustness for sustainable and cost-effective MG management.</p>','["Combined economic and emissions dispatch, microgrids, R\\u00fcppell fox optimizer, renewable energy"]',NULL,37,1,'2044 - 2062',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-15',2),
(6388,6388,1,'Non-Contractual Civil Liability for Deficiencies in Maternal-Neonatal Care in Peru','<p>This article analyzes extra-contractual civil liability arising from deficiencies in maternal and neonatal care in Peru, considering state obligations and the legal difficulties in determining damages caused during healthcare provision. Its objective was to analyze the configuration of this liability within public maternal and neonatal health programs during 2024-2025. Basic, qualitative research was conducted using legal interpretation and case analysis. Semi-structured interviews were conducted with eight lawyers, one physician, and one obstetrician, supplemented by a review of ten court cases using document analysis forms. The results identified difficulties in proving healthcare non-compliance, establishing causal links, and differentiating professional conduct from organizational deficiencies, particularly in cases of diagnostic delays, therapeutic omissions, and limitations in healthcare resources. The interviews and court rulings revealed differences in the assessment of medical records, expert reports, and the criteria used to quantify compensation. It was concluded that civil liability required proof of unlawful conduct, harm, causation, and the basis for attribution, without considering the existence of obstetric or neonatal complications sufficient. Due to the qualitative scope of the study, the findings were limited to the sources analyzed, although they offer legal criteria for evaluating future disputes related to compensation for healthcare damages.</p>','["Civil liability, maternal and child health, right to health, civil law, health policy"]',NULL,37,1,'2063 - 2076',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-15',3),
(5714,5714,1,'An Integrated Multimodal Machine Learning Framework for Parkinson’s Disease Screening Using Behavioral and Physiological Biomarkers','<p>Parkinson’s disease is often recognized late because clinical assessment depends on visible motor signs and on examiner judgment. Low-cost behavioral and physiological measurements could support earlier screening, but most computational studies analyze one signal type at a time. This study presents an integrated multimodal machine learning framework that combines voice, spiral drawing, wave drawing, electrocardiogram with oxygen saturation, and hand-worn gait signals acquired with inexpensive embedded hardware, and asks whether multimodal evidence can improve on single-modality screening. Each modality was processed with its own preprocessing and feature pipeline, and about twelve classifiers per modality were compared using accuracy, precision, recall, F1-score, and log loss. The best single-modality models were XGBoost for voice (90.00%), CatBoost for spiral (87.50%) and wave drawings (89.50%), gradient boosting for the electrocardiogram (96.26%), and AdaBoost for gait (85.71%). The system-level figure of 89.79% reported for the original prototype is shown to be the arithmetic mean of these five accuracies rather than the accuracy of a fused classifier. Because the five datasets were collected independently and are not linked to the same participants, subject-level fusion could not be evaluated. Instead, two fusion designs (feature-level and calibrated decision-level) and a validation protocol covering ablation, calibration, and repeated subject-independent splits are specified, and Wilson confidence intervals are reported, showing wide uncertainty for the smaller test sets (gait: 48.7% to 97.4%). Tree-based ensembles performed best for every modality, and electrocardiogram features were the most discriminative in the available data. Claims of multimodal superiority require participant-aligned data; the framework and protocol provide a basis for a rigorous evaluation of low-cost multimodal screening.</p>','["Parkinson\\u2019s disease, multimodal machine learning, gradient boosting, voice analysis, handwriting, gait, electrocardiogram, screening"]',NULL,36,1,'01 - 13','10.17762/jidmis.v3.5714',NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-09',1),
(5716,5716,1,'Explainable Multimodal Retinal Fundus Deep Learning for Cardiovascular Risk Assessment: Disentangling Image, Age and Sex Contributions to Carotid Intima-Media Thickening','<p>Carotid intima-media thickening is an early marker of atherosclerosis, a recognised indicator of cardiovascular risk and a predictor of stroke and myocardial infarction, but its measurement requires ultrasound and trained operators, which limits population screening. Deep learning on fundus photographs offers a low-cost route to cardiovascular risk assessment, and recent models report test AUCs above 0.90. However, these models have not been benchmarked against clinical baselines, so the true contribution of the retinal image remains unknown. In this paper, we present a rigorous multi-backbone benchmark of unimodal (image only) and multimodal (image, age and sex) models on the public China-Fundus-CIMT dataset of 2,903 patients. Bilateral fundus images were encoded with four pretrained backbones, including the retinal foundation model RETFound, and evaluated with repeated five-fold cross-validation, an age-and-sex reference model, age-matched testing, retinal-age analysis and the official test split. Multimodal fusion improved every backbone, raising the RETFound AUC from 0.821 to 0.852 (gain 0.031, 95% CI 0.023 to 0.039, p &lt; 0.001). On the official test split, our multimodal model reached 0.944, exceeding the published 0.904. The benchmark further identified age as the dominant signal: the age-and-sex reference reached 0.854, matching the best multimodal model, image models performed at chance in 576 age-matched pairs, and image-predicted retinal age reproduced the image-only AUC. This work establishes the reference performance that future fundus models must exceed and provides an open, reproducible evaluation protocol for developing retinal screening tools for cardiovascular risk.</p>','["Carotid intima-media thickness, Fundus photography, Retinal foundation model, RETFound, Multimodal deep learning, Age confounding, Cardiovascular risk screening, Incremental predictive value"]',NULL,36,1,'14 - 41',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-09',2),
(5717,5717,1,'PsyFusionNet: A Psychologically Informed Noise-Resilient Framework for Early Mental Health Disorder Detection from Social Media','<p>With the rise of social media, there has been an advancement in the early detection of mental disorders through the analysis of the message content expressed by users. This procedure is nevertheless challenging because of language complexity, emotional structures, noise in the process of the message processing, and also multi-dimensionality of the text meaning. In order to deal with these drawbacks, this work proposes PsyFusionNet, a unique model for the early detection of mental disorders in social networks. The model comprises the Psyclean-ELECTRA module and an Adaptive Confidence Label Refinement (ACLR) module. The former one refuses the problematic words with regard to the meaning and context of the user’s statement. The second module evaluates the quality of labels and makes corrections for them taking into account the meaning of the text, its reliability, and emotions conveyed through the text. Then the text is processed by a Cognitive–Affective Cross-Attention Fusion Network (CAFNet). Finally, the Psychological Importance-Guided Feature Compression (PIGFC) module allows getting rid of unnecessary features by means of separating them from those important ones. Finally, a Hierarchical Emotion-Aware Transformer (HEATNet) needs to develop a model to capture hierarchical contextual dependencies and long-range cognitive-emotional relations to correctly classify mental illnesses. Evaluation of the system on a large-scale social media mental health dataset shows that the framework consistently does much better than others when it comes to accuracy, precision, recall, and F1 score, while also being more reliable when dealing with noisy text and annotation uncertainty. Experimental validation of the proposed methodology on a large-scale dataset demonstrates that the proposed methodology achieves higher total classification accuracy 95.1%.</p>','["Mental Health, CAFNet, Psyclean-ELECTRA, PIGFC, HEATNet"]',NULL,36,1,'42 - 58',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-09',3),
(5283,5283,1,'Implementation of Multiple UAV (Unmanned Aerial Vehicle) Algorithm for Different Mission Profile with Different Capability','<p>Over the last decade, the drone industry has grown tremendously across various sectors such as agriculture, trans-portation, surveillance, and more. In defense, drones play a vital role, especially in forms like FPV (First-Person View) kamikaze drones, which have become game-changers in modern warfare with their ability to operate in swarms.However, navigating a swarm of drones with different missions and different payloads through uncertain environments presents significant challenges. The evaluation processes often take considerable time, causing delays in real-time command execution.This paper identifies gaps in different capabilty in swarm of drone for operational efficiency of drone swarms from the initial to the final point. It analyzes various parameters such as the number of nodes, velocity, acceleration, distance, payload effects on velocity, and path comparison. By applying intelligent swarm algorithms, the study addresses and fixes these flaws, optimizing swarm performance across different parameters. This paper works on different missions involving drones with varying capabilities and payload weight factors. It investigates key aspects such as the number of nodes, trajectory quality, energy efficiency, and computational efficiency to optimize swarm performance under diverse conditions.</p>','["Swarm of Drones , Rapidly Exploring Random, A*,ACO Algorithm,PCO Algorithm"]',NULL,35,1,'01 - 09','10.17762/jidmis.v3.5283',NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-10-22',1),
(5284,5284,1,'Sugarcane Baggage Ash Used as a Locally Available Cementitious Material for Enhancing the Property of PQC','<p>The demand of the pavement construction materials is on the rise and the Portland cement production has been associated with the environmental impacts so that there has been a need for sustainable supplementary cementitious materials. The study focuses on the enhancement of properties of the Plain Cement Concrete (PQC) with locally available material called sugarcane bagasse ash (SCBA) and solving the problem of agricultural waste disposal along with consumption of cement. The suggested methodology would involve collection and characterization of both cement and aggregate, as well as water, before dried, burning, grinding and sieving of SCBA was performed. Different amounts of SCBA replacement and without any SCBA (a control mixture) are prepared as PQC mixtures and the mixtures are subjected to a controlled curing process. The basis for determining an effective replacement level is based on compressive strength, flexural strength, water absorption, abrasion and permeability. There is also some numerical evidence for the SCBA potential from previous work, e.g. a 14.8% gain in 28 day compressive strength at 15% replacement, as well as 6.51% and 9.65% gains in flexural and compressive strength respectively at 20% replacement. The objective of the study is to identify a balanced proportion for SCBA that provides mechanical and durability performance and enhances sustainability practices, resource utilization and waste management during PQC pavement placement.</p>','["Sugarcane Bagasse Ash, Plain Cement Concrete, Supplementary Cementitious Material, Compressive Strength, Sustainable Pavement Construction."]',NULL,35,1,'10 - 28',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-10-22',2),
(5285,5285,1,'Artificial Intelligence in Financial Decision-Making: Transforming Risk Assessment, Investment Strategies, and Market Efficiency','<p>Financial institutions now use machine learning, deep learning, and language models across three decision domains: credit and fraud risk assessment, security selection and portfolio construction, and trade execution. This paper reviews the empirical record for each domain and asks what the evidence shows about accuracy, durability, fairness, and effects on market quality. The review synthesizes foundational theory (Markowitz, Fama, Grossman and Stiglitz, Lo) with peer-reviewed empirical studies and supervisory documents. The main findings are as follows. In credit, machine-learning models trained on 2005–2009 bank data cut credit-line losses by 6–25 percent relative to conventional scoring, but gains from machine learning in U.S. mortgage lending accrue unevenly across racial groups. In asset pricing, neural networks trained on roughly 30,000 U.S. stocks over 1957–2016 achieve monthly out-of-sample R² near 0.4 percent, which is small yet economically meaningful, while an LSTM strategy on S&amp;P 500 constituents earned 0.46 percent per day before costs yet decayed to near zero after 2010. In market structure, algorithmic trading narrows spreads in normal conditions but contributed to the 6 May 2010 Flash Crash. Two comparative tables map techniques to reported results and map principal risks to evidence and controls. The paper concludes that AI improves predictive accuracy in credit and fraud detection most reliably, delivers fragile and decaying gains in return prediction, and creates governance obligations that existing model-risk regulation only partly covers.</p>','["Artificial Intelligence, Machine Learning, Credit Risk, Algorithmic Trading, Asset Pricing, Market Efficiency, Explainable AI, Model Risk."]',NULL,35,1,'29 - 39',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-10-22',3),
(4880,4880,1,'Inspection Games as a Teaching Strategy for Environmental Audit Management and Foreign Trade Compliance in International Negotiations','<p>Environmental audit management and international trade compliance require professionals to make strategic decisions under incomplete information. This study investigates how observed behavior in inspection games can inform an instructional design for these tasks. We conduct a secondary econometric analysis of publicly archived experimental microdata, retaining 8,750 unique dyad round observations from 125 dyads across 21 sessions and seven incentive regimes. A linear probability model with round fixed effects and session clustered inference estimates differences in work decisions relative to the baseline. Work occurs in 53.4 percent of baseline decisions, compared with 85.2 percent under high discretion rewards and 89.1 percent under high discretion combined incentives. The corresponding adjusted differences are 31.8 and 35.7 percentage points. Logit estimation, separate early and late round estimates, and session deletion analyses preserve the qualitative ranking. However, exact session label permutations for the high discretion reward versus punishment comparison yield a two sided p value of 0.10, underscoring the limited number of independent sessions. These findings support using competing incentive structures as material for classroom analysis rather than establish educational effectiveness. We translate the evidence into an environmental audit and trade negotiation exercise with documentary verification, risk allocation, and a proposed randomized educational evaluation. No learning, environmental, or trade outcomes are measured in the archived experiment. The contribution is a reproducible behavioral evidence layer coupled with a testable instructional framework.</p>','["inspection games", "environmental auditing", "international trade compliance", "game based learning", "experimental microdata", "clustered inference"]',NULL,34,1,'01 - 16',NULL,'Brayan Alexis Villarreal Chiriboga, Juan Federico Villacis Uvidia, María José Álvarez Verdezoto, Alejandro Carlos Lalama Freire',2026,'https://creativecommons.org/licenses/by/4.0/','published','2026-10-10',1),
(4881,4881,1,'Artificial Intelligence in Nursing Leadership: A Scoping Review of Decision Support, Organizational Readiness, and Ethical Governance','<p>Artificial intelligence (AI) is increasingly used in healthcare decision support, workforce management, documentation, predictive analytics, and organizational information systems. This scoping review mapped and synthesized evidence on the role of nursing leadership in AI-enabled healthcare decision making and organizational implementation, emphasizing decision support, organizational readiness, workforce and operational integration, leadership influences on AI adoption, and ethical governance. Reporting was guided by the Preferred Reporting Items for Systematic Reviews and Meta-Analyses Extension for Scoping Reviews (PRISMA-ScR). A primary OneSearch search identified 15 unique records, and a supplementary PubMed search using expanded leadership and AI-readiness terminology yielded 45 records within the January 1, 2021-August 31, 2026 publication period. After eligibility assessment and reconciliation, 16 studies met the final inclusion criteria. Three interrelated themes were identified: (1) AI-enabled decision support and operational efficiency; (2) organizational readiness, leadership capability, and workforce adoption; and (3) ethical governance, professional accountability, and human oversight. AI showed potential to support documentation, patient-flow management, workforce planning, and administrative decision making. Implementation was associated with leadership self-efficacy, AI literacy, organizational resources, implementation support, and adaptive leadership behaviors. Human verification, transparency, privacy, accountability, and nursing participation in governance remained central across the evidence. These findings position AI integration in nursing leadership as a sociotechnical organizational process requiring alignment among technological capability, leadership readiness, workforce adoption, and human-centered governance.</p>','["artificial intelligence", "nursing leadership", "nurse managers", "decision support", "organizational readiness", "artificial intelligence governance", "workforce management"]',NULL,34,1,'17 - 35',NULL,'Timothy Ortiz, Siritorn Yingrengreung, Werayuth Srithumsuk',2026,'https://creativecommons.org/licenses/by/4.0/','published','2026-10-10',2),
(4882,4882,1,'Phishing, OTP Fraud and Banking Scams: Who Is Legally Liable? A Critical Analysis of Liability for Unauthorised Digital Banking Transactions in India','<p>Due to the growth of online banking, UPI, OTP-based authentication and mobile payment systems in India, the problem of digital banking fraud has escalated. The present paper investigates the legal apportionment of liability in phishing scams, OTP frauds, impersonation scams, unauthorised transactions and mule-account network. It examines the regulatory regime that the reserve bank of India has formulated, the applicable statutory laws, court rulings, consumer laws, and roles of banks and payment services providers. Specific focus is on the divergence between authentication and genuine authorisation, negligence by the customers and failures in the institutional security systems, causation and obligations to report. The paper concludes that the usage of OTPs should not necessarily prove customer consent and suggest a risk-based liability framework that includes proper authorisation, level of culpability, bank failure, causation, mitigation, and prevention capabilities. This will be done by providing a more balanced foundation of distributing financial loss in more sophisticated fraud in digital banking.</p>','["Renewable Energy Prediction, Machine Learning, Smart Grid, Explainable AI, Energy Conservation, Green Computing"]',NULL,34,1,'36 - 53',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-10-10',3),
(4470,4470,1,'GSI-GreenNet: A Sustainability Assessment and Green AI Model Framework for Software Firms','<p>Even though AI-driven services are becoming more important to software companies, conventional model development pipelines pay little attention to the economic and environmental effects of these services. While there has been some recent work on green software engineering (e.g., GREENSOFT, GreenSDLC) and green AI, the majority of these efforts have focused on large-scale providers and do not provide small businesses with practical advice on how to incorporate energy, carbon, and cost considerations into the machine learning lifecycle. In this study, to present GSI-GreenNet, a framework for sustainability evaluation and model building that guides the development of energy-efficient models by evaluating AI workloads simultaneously along economic, social, and environmental dimensions. As part of its specification, the framework establishes the Green Software Index (GSI), which is a weighted indicator of training energy, carbon emissions, TCO, and stakeholder satisfaction. To evaluate the suggested GSI-GreenNet, along with AO-DNN, EA-NAS, CT-Train, and a standard AI classification workload after instantiating the framework. Although it maintains a competitive accuracy rate (96.3% vs. 96.8%), experiments reveal that GSI-GreenNet decreases training energy from 52.0 to 21.5 kWh and carbon emissions from 30.2 to 12.4 kgCO₂e. The total cost of ownership (TCO) drops by 29% compared to AO-DNN, and developers, operators, and end users are all happier as a result. With GSI-GreenNet, the resultant GSI is 0.78, up from 0.51 with AO-DNN. These findings show that by implementing the suggested framework, small and medium software companies can attain significant sustainability benefits while maintaining performance.</p>','["Software firms", "Green Software Index", "Total cost of ownership", "Carbon emissions", "Sustainability assessment"]',NULL,32,1,'01 - 17',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-10-02',1),
(4471,4471,1,'Digital Transformation and Firm Growth in Moroccan SMEs: The Mediating Role of Innovation Capability and the Moderating Role of Perceived Institutional Quality','<p>Digital transformation offers small and medium-sized enterprises (SMEs) opportunities for growth, but its association with growth may depend on organizational capabilities and institutional conditions. This study examines the relationship between digital transformation and growth in Moroccan industrial SMEs, with innovation capability as a mediator and perceived institutional quality as a moderator. Drawing on the resource-based view and institutional theory, we analyze survey data from 300 managers of Moroccan industrial SMEs using partial least squares structural equation modeling (PLS-SEM). The measurement model demonstrates satisfactory reliability, convergent validity, and discriminant validity. Digital transformation is positively associated with innovation capability (β = 0.488, p &lt; .001) and, to a lesser extent, directly with firm growth (β = 0.161, p = .002). Innovation capability is positively associated with growth (β = 0.455, p &lt; .001) and partially mediates the digital transformation–growth relationship (indirect effect = 0.222, p &lt; .001). Perceived institutional quality is positively associated with growth (β = 0.138, p = .005) and positively moderates the direct relationship between digital transformation and growth (β = 0.125, p = .012), although the interaction effect size is small (f² = 0.024). The model explains 34.7% of the variance in firm growth and 23.8% in innovation capability, and PLSpredict indicates satisfactory out-of-sample predictive power. The findings support an integrated resource-based and institutional account in which innovation capability plays a central role in the association between digital transformation and growth. They suggest that managers should consider digital investment alongside the development of innovation processes. Because the design is cross-sectional, the results are interpreted as associations rather than causal effects.</p>','["Digital transformation", "innovation capability", "perceived institutional quality", "firm growth", "SMEs", "Morocco", "PLS-SEM"]',NULL,32,1,'18 - 33',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-10-02',2),
(4472,4472,1,'Digital Capabilities and Hospital Performance in the AI-Enabled Healthcare Era: The Mediating Role of Digital Innovation Capability','<p>The object of this study is organizational performance (OP) in hospitals within the Indian healthcare sector. The present study investigates the impact of digital capabilities [Artificial Intelligence (AI) adoption, Digital Human Capital (DHC), Digital Leadership (DL), and Organizational Agility (OA)] on OP through the mediating role of Digital Innovation Capability (DIC). Nowadays, hospitals are gradually implementing AI and digital technologies. However, studies that explore the combined effect of these digital capabilities on DIC and, subsequently, OP are still limited. The study addresses the gap by proposing an integrated structural model that links major digital capabilities and examines their effects on DIC and its consequent impact on OP. The study employed PLS-SEM to test data from 423 hospital managers and administrators. The results indicate that AI Adoption (β = 0.257, p &lt; 0.01), DHC (β = 0.204, p &lt; 0.01), DL (β = 0.223, p &lt; 0.01), and OA (β = 0.274, p &lt; 0.01) significantly influence DIC. The effect of DIC on OP is significant (β = 0.888, p &lt; 0.01), explaining 78.8% of the variance, and the model accounts for 83.0% of the variance in OP. The findings suggest that OP in hospitals is mainly determined by the integration of multiple digital capabilities through DIC, rather than by any single digital capability alone. The distinctive feature of the study is the development of an integrated framework by coalescing digital capabilities, thus positioning DIC as the key mechanism linking to OP in hospitals. The results can be applied in practice by hospitals to support digital capabilities, develop DIC, and strengthen OP by integrating AIA, DHC, DL, and OA effectively during digital transformation initiatives.</p>','["AI Adoption, Digital Leadership, Organizational Performance, Hospitals, Digital Transformation"]',NULL,32,1,'34 - 52',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-10-02',3),
(4698,4698,1,'An Optimal Ensemble Model Using Lyrebird Optimization Algorithm (LOA) for Plant Leaf Disease Classification','<p>Leaf diseases significantly influence plant health and agricultural productivity, necessitating accurate and efficient diagnostic systems. The Enhanced Attention Residual U-Net and Attention-enhanced EfficientNetB3 (EARUAE) framework was proposed to overcome the difficulties like variations in lighting, leaf texture, background clutter, and sparsely distributed diseased regions that hinder accurate leaf disease detection. The framework adopts bit-level attention mechanism for precise segmentation of diseased regions, stacked pre-trained CNN models for features extraction, and the EfficientNetB3 model with spatial attention for multiclass leaf disease classification. Although effective, the proposed feature extraction and classification structure of EARUAE might restrict the capacity to obtain multiple and complementary feature representations, especially for complex, highly cluttered, or degraded leaf images. In order to tackle this gap and build upon those progress, this study presents an Ensemble of Optimized EARUAE (EO-EARUAE) framework. The proposed ensemble architecture combines several configurations of EARUAE with the pre-trained CNN feature extraction models to generate different and complementary features representations. In addition, the Lyrebird Optimization Algorithm (LOA) is used to tune parameters and select features among the ensemble members. This work integrates diverse attribute representations with optimization in order to improve the consistency and precision of multiclass leaf disease analysis in difficult image scenarios (EO-EARUAE). Extensive evaluation demonstrates that EO-EARUAE significantly improves leaf disease detection under challenging conditions, providing a dependable solution for agricultural applications.</p>','["Lyrebird Optimization Algorithm", "Leaf disease classification", "Hyperparameter Tuning", "Ensemble", "EfficientNetB3"]',NULL,33,1,'01 - 13',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-07-15',1),
(4772,4772,1,'Enhancing Energy Efficiency and Load Fairness in Cloud-IoT Healthcare Networks Through Hybrid Scheduling and VM Migration','<p>Cloud-based healthcare services utilizing Internet of Things (IoT) present a promising avenue for advancing medical applications. User satisfaction is impacted by Task Scheduling (TS), which is a vital component of Cloud-IoT-based healthcare services. To tackle this challenge, a Hybrid Quasi-Recurrent Neural Network (Quasi-RNN) with Walrus Optimization Algorithm (WOA) and Deviation Backfilling (HQRWDB) has been developed. However, the varying lengths, start times, and execution times of tasks assigned to Virtual Machines (VMs) make Load Balancing (LB) among VMs or Physical Machines (PMs) a complex issue in the Cloud-IoT environment. Overloading or underloading a host or server during cloud access can result in high execution time and energy consumption. To mitigate these issues, a balanced distribution of tasks across all resources, known as LB, is essential. The LB technique should ensure optimal utilization of all VMs. In order to achieve a balance between energy consumption and load fairness across PMs in heterogeneity Cloud-IoT healthcare networks, this study proposes a combined TS as well as LB approach that leverages the WOA. In order to implement effective LB, this work seeks to determine the optimal mapping connection between chosen tasks and VMs for PM allocation. The WOA is used to choose the best VMs and workloads to migrate to the best PMs all at once. Every VM''s fitness function is used to choose the best workloads, and every PM''s fitness function is used to find the best virtual machines to migrate. Thus, it achieves optimal use of VM capabilities and enhances system performance through balanced TS and LB. Finally, compared to other algorithms in the Cloud-IoT paradigm, the HQRWDB-TSLB algorithm achieves better outcomes in TSLB simulations.</p>','["Cloud-IoT, Task scheduling, Load balancing, VM migration"]',NULL,33,1,'14 - 29',NULL,'M Anitha, K Nandhini',2026,'https://creativecommons.org/licenses/by/4.0/','published','2026-10-08',2),
(4860,4860,1,'Analysis of Institutional, Socio-Cultural, and Political Factors in the Implementation of Sustainable Governance of Medium-Sized Enterprises in Makassar City','<p>The implementation of sustainable governance for medium-sized enterprises at the local level is determined not only by policy design but also by the institutional, socio-cultural, and political contexts in which it operates. This study aims to analyze the institutional, socio-cultural, and political factors that act as both barriers and drivers in the implementation of sustainable governance for medium-sized enterprises in Makassar City, as well as their implications for the effectiveness of local policies. This research employs a qualitative approach using a case study design. Data were collected through in-depth interviews, observations, and a review of relevant policy documents, and were analyzed thematically based on governance and sustainability perspectives. The findings indicate that, institutionally, fragmentation of authority among local government agencies and weak cross-sectoral coordination hinder the integration of sustainability policies at the implementation stage. From a socio-cultural perspective, the orientation of medium-sized business actors toward short-term profit, coupled with limited incentives and inadequate institutional support, constrains the adoption of sustainable business practices. Meanwhile, local political dynamics that prioritize the achievement of short-term development targets affect policy consistency and the allocation of resources toward sustainability agendas. These findings emphasize that the effectiveness of sustainable governance for medium-sized enterprises results from a complex interaction between institutional structures, the socio-cultural characteristics of business actors, and local political priorities. Therefore, strengthening sustainability policies requires an adaptive, well-coordinated governance approach that is sensitive to local contexts.</p>','["Governance, Medium-Sized Enterprises, Institutional Factors, Socio-Cultural Factors, Politics."]',NULL,33,1,'30 - 49',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-10-10',3),
(4042,4042,1,'When Collective Intelligence Fails: Informational Reverberation and a Polyhedral Framework for Diagnosing Failure Modes in Collaborative Communication','<p><br/>Collective intelligence requires not only the diversity of the participants, but also the ability of information to remain, flow and evolve in interaction. However, the current thinking on collective intelligence, cybernetics and structured processes of collaboration focuses on few aspects related to the dynamics of ideas when they are introduced into a communication system. Based on the conceptual elements of acoustic reverberation, recurrent neural activity and cybernetic feedback, this study proposes a concept of informational reverberation: a process in which ideas persist, propagate and are semantically transformed between participants. A Polyhedral Reverberation Framework (PRF) is created to imagine other communication regimes from informational extinction and fragmentation to distributed emergence and excessive convergence. The study serves as an exploratory empirical test bed, based on the AMI Meeting Corpus, and quantifies four dimensions of communication: participation entropy, idea persistence, cross-participant propagation and semantic transformation. Based on preliminary analysis, participation distribution alone was not able to provide a representative measure of informational influence. Rather, ideas vary widely in their ability to endure, transcend participant borders and mutate as they are subsequently interacted with. There are four potential failure modes: reverberation extinction, reverberation fragmentation, synchronization collapse and resonance capture. The study adds a process level perspective that connects the requisite variety aspects with what is suggested as the requisite reverberation. It offers a preliminary set of measures against which future comparative studies can be conducted in order to determine if the communication system unique to Syntegration® produces an optimal reverberation regime, leading to higher quality collective intelligence.</p>','["Informational Reverberation", "Collective Intelligence", "Syntegration", "Polyhedral Cybernetics", "Participation Entropy", "Idea Propagation", "Semantic Transformation", "Requisite Variety", "Collaborative Meetings."]',NULL,31,1,'01 - 13','10.17762/jidmis.v3.4042',NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-24',1),
(4043,4043,1,'Organizational Collaborative Capacity in Improving the Human Development Index in Tambrauw Regency','<p>Improving the Human Development Index (HDI) requires collaboration among organizations because education, health, and a decent standard of living are interconnected development dimensions. In Tambrauw Regency, however, human development continues to face challenges related to geographical accessibility, limited resources, fragmented information, and weak coordination among organizations. This study aims to analyze organizational collaborative capacity in supporting HDI improvement in Tambrauw Regency. A qualitative exploratory approach was employed. Data were collected through in-depth interviews, observation, and documentation involving 16 informants from government institutions, statistical agencies, non-governmental organizations, sub-district governments, and community representatives. Data were analyzed using an interactive model consisting of data condensation, data display, and conclusion drawing, while data validity was established through source triangulation, methodological triangulation, and member checking. The findings show that organizational collaborative capacity remains limited. Interdependence among organizations exists in the implementation of education, health, and decent living programs, but it has not been sufficiently transformed into integrated joint action. Membership and role distribution remain predominantly sectoral and are not supported by a permanent cross-sector collaborative structure. Resources, including budgets, human resources, and infrastructure, are available but have not been optimally integrated across organizations. Information is available through government institutions and other actors but is primarily used for sectoral planning and reporting rather than collective decision-making. Organizational learning also remains fragmented, with evaluation processes largely conducted within individual organizations. The study concludes that strengthening organizational collaborative capacity requires institutionalized cross-sector collaboration, integrated resource and information management, clearer actor roles, and collective learning mechanisms to support more coordinated, adaptive, and sustainable HDI improvement in Tambrauw Regency.</p>','["organizational collaborative capacity", "cross-sector collaboration", "human development index", "Tambrauw Regency", "collaborative governance"]',NULL,31,1,'14 - 26',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-24',2),
(4044,4044,1,'An Optimized Hybrid Deep Learning Framework with Multi-Scale CNN, BiGRU, and Self-Attention for SMS Spam Detection Using Seagull Optimization-Based Feature Selection','<p>Spam remains a persistent problem for SMS, and the messages themselves keep changing as senders adapt to whatever filter is placed in front of them. This paper describes a hybrid deep learning model for SMS spam classification that combines a multi-scale convolutional block, a bidirectional gated recurrent unit (BiGRU), and a self-attention layer. Feature selection is handled separately by the Seagull Optimization Algorithm (SOA), used as a wrapper over TF-IDF features, which cut the feature space by roughly half without a matching loss in accuracy. The proposed CNN-BiGRU-Attention model was compared against six traditional machine learning classifiers and four deep learning baselines on the SMS Spam Collection dataset. It reached 98.83% accuracy, 97.89% precision, and 99.69% specificity. Both the precision and the specificity were the best figures in the comparison, and the model misclassified only three of the 966 legitimate messages in the test set. For a production filter, where wrongly blocking a real message costs more than letting a spam message through, that error profile matters more than a marginal gain in F1-score.</p>','["SMS spam detection", "deep learning", "convolutional neural network", "bidirectional gated recurrent unit", "seagull optimization algorithm", "feature selection"]',NULL,31,1,'27 - 42',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-24',3),
(3680,3680,1,'The Confluence of Literary Criticism, Mathematics and Linguistics in the Idea of Hierarchization','<p>The research study titled “The Confluence of Literary Criticism, Mathematics and Linguistics in the Idea of Hierarchization” is interdisciplinary in its nature as it projects the idea of fluidity between two or more entities thereby subverting the notion of rigid boundaries or watertight compartments or else pigeonholes. It is an instance of qualitative and applied research. The theory of analogy has been used in the research study to highlight the similarities in certain properties related to the concepts across the disciplines. Postmodernism is a theoretical approach that rejects grand narratives that claim to provide a total explanation of society, and universal truths that are relevant to a particular context, culture, or individual. Thus, the idea of hierarchization has been placed in the context of Postmodernism. The primary texts used for research are A Reader’s Guide to Contemporary Theory (1985) by Raman Selden, Linguistics Simplified Semantics (2024) by D. Thakur, and “The Curious History of Venn Diagrams” (2025) by Jack Murtagh in Scientific American. Postmodernism embraces fragmentation of ideas bringing about diversity and fluidity of meanings, identities, cultures, power, politics, reality, knowledge, and individuals. It focusses on the overlaps or the fusions of the structures. It rejects the social construction of reality as a universal objective phenomenon through language, culture, and social interaction. Postmodernism emphasizes upon multiplicity and difference. It posits the existence of multiple and contradictory views based on heterogeneity that replaces the single unified view based on homogeneity. The same idea is illustrated through the concept of Venn Diagrams in Mathematics. A Venn Diagram is a visual tool that projects relationships between two or more sets of entities that may be similar or different thereby foregrounding fluidity in the two or more sets. The Venn Diagrams manifest the idea in the form of circles or sets, overlapping areas, unique areas, and a universal set. The fluidity or fusion of ideas in Postmodernism is highlighted by the idea of overlapping areas as represented by overlapping sets or fused circles in the Venn Diagrams. The existence of co-hyponyms in the ideas of hypernymy and hyponymy in Linguistics manifests the same idea of fluidity or fusion in Postmodernism and that of the overlapping areas in the Venn Diagrams. The idea of fluidity or fusion of ideas in Postmodernism may also be manifested by the concentric circles or sets in Venn Diagrams and by the idea of superordinate and hyponyms in Linguistics. The immediate use of these ideas may be beneficial in studying hierarchies or the process of hierarchization, categories or the processes of categorization especially in the case of Benjamin Bloom’s taxonomy that classifies educational learning objectives into the levels of complexity and specificity and serves to structure curriculum learning objectives, assessments, and objectives.</p>','["Literary Criticism, Mathematics, Linguistics, Fluidity, Fusion, Venn Diagrams, Sets, Hypernymy, Hyponymy, Superordinate etcetera."]',NULL,30,1,'01 - 10',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-21',1),
(3682,3682,1,'Regime-Aware Evidence Fusion for Calibrated Forecasting of Non-Stationary Time Series','<p>Non-stationary forecasting is not the same as forecasting in average terms; forecasting performance depends on the ability to forecast regime changes rather than the ability to fit perfectly in average cases. Regime shifts, calendar effects, policy interventions, and unreliable instrumentation constantly disrupt energy grids, transportation networks, and sensor-intensive urban systems, while even the most commonly-used energy- and transport-related learning-based forecasters typically assume that such systems are near-stationary or incorporate a fragile change-point detector as a pre-processing module. We choose a rather alternative path: discover the regime, gain insight into context, tailor or rate uncertainty, and continuously adapt. All these steps are learnable steps in the pipeline, from the beginning, not added on in a later phase. The five phases create this structure, which functions as follows. Under a causal-invariance constraint, a causal regime tokeniser (CaRT) is able to learn causal-invariance changes in tokens and small context pieces. A Wavelet–State-Space Dual-Path Predictor (WSDP) subsequently is used to predict in the short, medium and long-range combining regime conditioned wavelet decomposition with a neural path space model. A module called ''evidence-weighted fusion'' (EviFuse) combines the two forecasts with a (reliability-based) ''weight'' determined by the residual. A counterfactual, cross-regime validation suite (CF-XValid) is introduced to stress-test the entire pipeline system, but not just rolling splits to generate new counterfactual scenarios. Last, a drift-aware continual-learning module (DriftShield-ACL) is utilized to maintain honest uncertainty estimates in production with light-weight adapter updates and conformal online updates. The framework reduces mean absolute error by 12–18% compared with the best of three current frameworks on four multivariate, highly non-stationary benchmarks, and lowers the RMSE across long-horizon (96-step) testing by 10–15% compared to the best of three contemporary ones in the targeted 96-step horizon. Its error rate drops more so when up to 20% of exogenous inputs are unavailable, as compared to any baseline, and its 90% prediction intervals remain around nominal (88–89%) as compared to many baselines, which are one or more points below. With compound stress (fast changing levels, beds of high demand, loss of sensors), the worst-case error decreases by approximately 20% compared to the best baseline. Overall, the findings indicate that the regime awareness method, the multi-scale modelling approach, the evidence-based fusion approach and the calibrated adaptation method are more effective as an integrated design of a "combined system" rather than simply as a collection of fixes and more effective when tested within robustness and deployment trust, not only average accuracy.</p>','["Non-Stationary Time Series, Regime-Aware Forecasting, Evidence-Based Fusion, Uncertainty Calibration, Continual Learning"]',NULL,30,1,'11 - 28','10.17762/jidmis.v3.3682',NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-21',2),
(3683,3683,1,'Benchmarking Deep Learning Architectures for Multi-Class Lemon Leaf Disease Classification','<p>Accurate and early detection of citrus leaf diseases is essential for maintaining lemon crop health and yield. This work presents a comparative evaluation of four deep learning architectures — CNN, CNN+LSTM, ResNet50, and DenseNet121 — for multi-class classification of lemon leaf diseases using image-based data. A standardized image preprocessing pipeline was developed, including resizing, normalization, and data augmentation techniques to improve model generalization. Each model was trained and evaluated under identical conditions to ensure fair benchmarking. Experimental results demonstrated that ResNet50 outperformed all other models, achieving the highest accuracy of 90.59%, precision of 91.73%, and F1-score of 89.73%, owing to its residual learning and deep feature extraction capability. DenseNet121 followed with 85.15% accuracy, while the lightweight CNN model offered a competitive 80.20% accuracy despite its simplicity. In contrast, CNN+LSTM underperformed with only 55.45% accuracy, indicating that temporal layers were ineffective for static image classification tasks. These findings highlight the effectiveness of deep convolutional backbones — particularly residual and densely connected networks — in extracting discriminative features for plant disease detection. The study lays a robust foundation for developing hybrid or ensemble models that further enhance diagnostic accuracy in precision agriculture.</p>','["Lemon Leaf Disease, Deep Learning, CNN, ResNet50, DenseNet121, Image Classification, Precision Agriculture."]',NULL,30,1,'29 - 54','10.17762/jidmis.v3.3683',NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-21',3),
(3345,3345,1,'Modeling of Carcinogenesis Using Two Markov Models','<p>In this paper, two Markov Chain Models, Model A and Model B for analysis and interpretation of the stages of cancer in the patients are proposed. Since Markov process is a stochastic process, under which movement occurs from one stage (state) to another, Model A and Model B are proposed based on this. Using model A we obtain the maximum likelihood estimation of transition probabilities and prove that the diagonal probabilities can expressed in terms of Eigen values. Using Model B we derive the expected passage time between two states.</p>','["Carcinogenesis", "Estimation", "State", "Markov Chain."]',NULL,29,1,'01 - 10',NULL,NULL,NULL,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-10',1);
